:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --primary: #0f3460;
  --accent: #e94560;
  --text: #eaeaea;
  --text-dim: #a0a0b0;
  --focus: #f5c542;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border-radius: 16px;
  padding: 32px 24px;
  width: 100%;
  max-width: 400px;
  text-align: center;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  border: 2px solid var(--primary);
}

.title {
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 24px;
  font-weight: 700;
}

.timer {
  font-size: clamp(3rem, 18vw, 5rem);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  line-height: 1.1;
  margin-bottom: 24px;
  letter-spacing: 4px;
  color: var(--text);
  text-shadow: 0 0 12px rgba(233, 69, 96, 0.4);
}

.modes {
  display: flex;
  gap: 12px;
  margin-bottom: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.mode-btn {
  flex: 1 1 120px;
  padding: 12px 16px;
  font-size: 1rem;
  font-weight: 600;
  border: 2px solid var(--primary);
  border-radius: 8px;
  background: transparent;
  color: var(--text-dim);
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s, transform 0.1s;
  font-family: inherit;
}

.mode-btn:hover {
  background: var(--primary);
  color: var(--text);
}

.mode-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.mode-btn:active {
  transform: scale(0.97);
}

.mode-btn.active {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

.control-btn {
  flex: 1 1 120px;
  padding: 14px 20px;
  font-size: 1.1rem;
  font-weight: 700;
  border: none;
  border-radius: 8px;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, box-shadow 0.15s;
  font-family: inherit;
  min-width: 120px;
}

.control-btn:hover {
  background: #f05a72;
  box-shadow: 0 4px 12px rgba(233, 69, 96, 0.4);
}

.control-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.control-btn:active {
  transform: scale(0.97);
}

.control-btn.secondary {
  background: transparent;
  border: 2px solid var(--accent);
  color: var(--accent);
}

.control-btn.secondary:hover {
  background: var(--accent);
  color: #fff;
}

.status {
  font-size: 1rem;
  color: var(--text-dim);
  min-height: 1.5em;
  letter-spacing: 1px;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .timer {
    letter-spacing: 2px;
  }
  .mode-btn,
  .control-btn {
    flex: 1 1 100%;
  }
}

const WORK_TIME = 25 * 60;
const BREAK_TIME = 5 * 60;

let timeLeft = WORK_TIME;
let timerId = null;
let isRunning = false;
let mode = 'work';

const timerEl = document.getElementById('timer');
const statusEl = document.getElementById('status');
const startPauseBtn = document.getElementById('startPauseBtn');
const resetBtn = document.getElementById('resetBtn');
const workBtn = document.getElementById('workBtn');
const breakBtn = document.getElementById('breakBtn');

function formatTime(seconds) {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}

function updateDisplay() {
  timerEl.textContent = formatTime(timeLeft);
  document.title = `${formatTime(timeLeft)} - Pixel Pomodoro`;
}

function setMode(newMode) {
  if (isRunning) {
    stopTimer();
  }
  mode = newMode;
  timeLeft = mode === 'work' ? WORK_TIME : BREAK_TIME;
  updateDisplay();
  workBtn.classList.toggle('active', mode === 'work');
  workBtn.setAttribute('aria-pressed', mode === 'work');
  breakBtn.classList.toggle('active', mode === 'break');
  breakBtn.setAttribute('aria-pressed', mode === 'break');
  statusEl.textContent = mode === 'work' ? 'Work mode ready' : 'Break mode ready';
  startPauseBtn.textContent = 'Start';
  isRunning = false;
}

function stopTimer() {
  if (timerId) {
    clearInterval(timerId);
    timerId = null;
  }
  isRunning = false;
}

function tick() {
  if (timeLeft > 0) {
    timeLeft--;
    updateDisplay();
    if (timeLeft === 0) {
      stopTimer();
      startPauseBtn.textContent = 'Start';
      statusEl.textContent = mode === 'work' ? 'Work session complete! Take a break.' : 'Break over! Back to work.';
      timerEl.textContent = '00:00';
    }
  }
}

function startTimer() {
  if (timeLeft === 0) {
    timeLeft = mode === 'work' ? WORK_TIME : BREAK_TIME;
    updateDisplay();
  }
  isRunning = true;
  startPauseBtn.textContent = 'Pause';
  statusEl.textContent = mode === 'work' ? 'Working...' : 'On break...';
  timerId = setInterval(tick, 1000);
}

function pauseTimer() {
  stopTimer();
  startPauseBtn.textContent = 'Start';
  statusEl.textContent = 'Paused';
}

function toggleTimer() {
  if (isRunning) {
    pauseTimer();
  } else {
    startTimer();
  }
}

function resetTimer() {
  stopTimer();
  timeLeft = mode === 'work' ? WORK_TIME : BREAK_TIME;
  updateDisplay();
  startPauseBtn.textContent = 'Start';
  statusEl.textContent = 'Reset';
}

startPauseBtn.addEventListener('click', toggleTimer);
resetBtn.addEventListener('click', resetTimer);
workBtn.addEventListener('click', () => setMode('work'));
breakBtn.addEventListener('click', () => setMode('break'));

// Keyboard shortcuts: Space toggles, R resets, W work, B break
document.addEventListener('keydown', (e) => {
  if (e.target.tagName === 'BUTTON' && (e.key === ' ' || e.key === 'Enter')) return;
  if (e.key === ' ') { e.preventDefault(); toggleTimer(); }
  if (e.key === 'r' || e.key === 'R') resetTimer();
  if (e.key === 'w' || e.key === 'W') setMode('work');
  if (e.key === 'b' || e.key === 'B') setMode('break');
});

// Initialize
updateDisplay();
workBtn.setAttribute('aria-pressed', 'true');
breakBtn.setAttribute('aria-pressed', 'false');
